// Everything the visitor saves lives in this browser (localStorage).
const KEY_LIST = 'hikari.watchlist.v1';
const KEY_HISTORY = 'hikari.history.v1';
const KEY_TRAILERS = 'hikari.trailers.v1';

const read = (key, fallback) => {
  try {
    const v = JSON.parse(localStorage.getItem(key));
    return v ?? fallback;
  } catch {
    return fallback;
  }
};
const write = (key, value) => {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch {
    /* storage full or blocked: keep working without saving */
  }
  window.dispatchEvent(new CustomEvent('hikari:store', { detail: { key } }));
};

// Watchlist: [{ id, added }]
export const getWatchlist = () => read(KEY_LIST, []);
export const inWatchlist = (id) => getWatchlist().some((x) => x.id === id);
export const toggleWatchlist = (id) => {
  const list = getWatchlist();
  const has = list.some((x) => x.id === id);
  write(KEY_LIST, has ? list.filter((x) => x.id !== id) : [{ id, added: Date.now() }, ...list]);
  return !has;
};

// History: [{ id, season, ep, at }] newest first, one entry per show.
export const getHistory = () => read(KEY_HISTORY, []);
export const recordWatch = (id, season, ep) => {
  const list = getHistory().filter((x) => x.id !== id);
  write(KEY_HISTORY, [{ id, season, ep, at: Date.now() }, ...list].slice(0, 50));
};
export const lastWatched = (id) => getHistory().find((x) => x.id === id);
export const clearHistory = () => write(KEY_HISTORY, []);
export const removeHistory = (id) => write(KEY_HISTORY, getHistory().filter((x) => x.id !== id));

// Trailers the visitor picked themselves: { showId: youtubeId }
export const getCustomTrailer = (id) => read(KEY_TRAILERS, {})[id] || null;
export const setCustomTrailer = (id, yt) => {
  const all = read(KEY_TRAILERS, {});
  if (yt) all[id] = yt;
  else delete all[id];
  write(KEY_TRAILERS, all);
};

import '../style.css';
import { GENRES, SHOWS } from '../data.js';
import { esc, grid, page, params } from '../ui.js';

const SORTS = {
  popular: ['Popularity', (a, b) => b.popularity - a.popularity],
  newest: ['Newest', (a, b) => b.year - a.year || b.popularity - a.popularity],
  az: ['Alphabetical', (a, b) => a.title.localeCompare(b.title)],
  rating: ['Top Rated', (a, b) => b.score - a.score || b.popularity - a.popularity],
};

page('browse', (main) => {
  const p = params();
  let genre = GENRES.find((g) => g.toLowerCase() === (p.get('genre') || '').toLowerCase()) || '';
  let sort = SORTS[p.get('sort')] ? p.get('sort') : 'popular';
  let type = p.get('type') || 'all';

  main.innerHTML = `
    <div class="page-head container">
      <h1 class="page-title"></h1>
      <div class="browse-bar">
        <div class="chips" role="list"></div>
        <div class="browse-controls">
          <label class="select"><span class="sr-only">Type</span>
            <select id="type">
              <option value="all">All types</option><option value="series">Series</option><option value="movie">Movies</option>
            </select></label>
          <label class="select"><span class="sr-only">Sort by</span>
            <select id="sort">${Object.entries(SORTS).map(([k, [label]]) => `<option value="${k}">${label}</option>`).join('')}</select></label>
        </div>
      </div>
    </div>
    <div class="container"><p class="result-count" aria-live="polite"></p><div id="results"></div></div>`;

  const chips = main.querySelector('.chips');
  const title = main.querySelector('.page-title');
  const count = main.querySelector('.result-count');
  const results = main.querySelector('#results');
  const sortSel = main.querySelector('#sort');
  const typeSel = main.querySelector('#type');
  sortSel.value = sort;
  typeSel.value = type;

  const render = () => {
    chips.innerHTML = ['', ...GENRES]
      .map((g) => `<button role="listitem" class="chip ${g === genre ? 'is-on' : ''}" data-genre="${esc(g)}" aria-pressed="${g === genre}">${g || 'All'}</button>`)
      .join('');
    title.textContent = genre ? `${genre} Anime` : sort === 'newest' ? 'New Anime' : 'Browse All Anime';
    document.title = `${title.textContent} · Hikari`;
    const list = SHOWS.filter((x) => !genre || x.genres.includes(genre))
      .filter((x) => type === 'all' || (type === 'movie' ? x.movie : !x.movie))
      .sort(SORTS[sort][1]);
    count.textContent = `${list.length} title${list.length === 1 ? '' : 's'}`;
    results.innerHTML = list.length ? grid(list) : `<div class="empty"><h2>Nothing here yet</h2><p>No titles match this combination. Try another genre.</p></div>`;
    const q = new URLSearchParams();
    if (genre) q.set('genre', genre);
    if (sort !== 'popular') q.set('sort', sort);
    if (type !== 'all') q.set('type', type);
    history.replaceState(null, '', `${location.pathname}${q.toString() ? `?${q}` : ''}`);
  };

  chips.addEventListener('click', (e) => {
    const b = e.target.closest('.chip');
    if (!b) return;
    genre = b.dataset.genre;
    render();
  });
  sortSel.onchange = () => { sort = sortSel.value; render(); };
  typeSel.onchange = () => { type = typeSel.value; render(); };
  render();
});

import '../style.css';
import { GENRES, SHOWS } from '../data.js';
import { browseUrl, esc, grid, icon, page, params } from '../ui.js';

const norm = (t) => t.toLowerCase().normalize('NFKD').replace(/[^a-z0-9 ]/g, '');

function score(show, q) {
  const title = norm(show.title);
  if (title.startsWith(q)) return 100;
  if (title.split(' ').some((w) => w.startsWith(q))) return 80;
  if (title.includes(q)) return 60;
  if (show.genres.some((g) => norm(g).startsWith(q))) return 40;
  if (norm(show.studio).includes(q)) return 30;
  if (q.length > 3 && norm(show.blurb).includes(q)) return 10;
  return 0;
}

page('search', (main) => {
  main.innerHTML = `
    <div class="search-band">
      <div class="container search-inner">
        <label class="search-field">
          <span class="sr-only">Search</span>
          ${icon.search}
          <input id="q" type="search" placeholder="Search titles, genres or studios" autocomplete="off" enterkeyhint="search">
          <button class="icon-btn search-clear" aria-label="Clear search" hidden>${icon.close}</button>
        </label>
      </div>
    </div>
    <div class="container" id="out"></div>`;

  const input = main.querySelector('#q');
  const clear = main.querySelector('.search-clear');
  const out = main.querySelector('#out');
  input.value = params().get('q') || '';

  const render = () => {
    const raw = input.value.trim();
    const q = norm(raw);
    clear.hidden = !raw;
    history.replaceState(null, '', `${location.pathname}${raw ? `?q=${encodeURIComponent(raw)}` : ''}`);
    if (!q) {
      out.innerHTML = `
        <h2 class="section-title">Browse by genre</h2>
        <div class="chips chips--wrap">${GENRES.map((g) => `<a class="chip" href="${browseUrl(g)}">${g}</a>`).join('')}</div>
        <h2 class="section-title">Popular right now</h2>
        ${grid([...SHOWS].sort((a, b) => b.popularity - a.popularity).slice(0, 12))}`;
      return;
    }
    const hits = SHOWS.map((show) => [show, score(show, q)]).filter(([, n]) => n > 0)
      .sort((a, b) => b[1] - a[1] || b[0].popularity - a[0].popularity).map(([show]) => show);
    out.innerHTML = hits.length
      ? `<h2 class="section-title">Top results <span class="muted">(${hits.length})</span></h2>${grid(hits)}`
      : `<div class="empty"><h2>No results for “${esc(raw)}”</h2><p>Check the spelling or try a genre such as <a href="${browseUrl('Fantasy')}">Fantasy</a>.</p></div>`;
  };

  input.addEventListener('input', render);
  clear.onclick = () => { input.value = ''; render(); input.focus(); };
  render();
  input.focus();
});

